"""CSV evaluation to validate tabular output (e.g., CSV) generated by a DataFrame program.

No backend dependencies or candidate execution. See README.md for compatibility.
"""
import csv
import hashlib
import io
from collections import Counter, defaultdict
from pathlib import Path

from .config import ConfigError, load_config
from .normalization import equal, normalize


class EvaluationFailure(Exception):
    def __init__(self, code, message, side=None, **detail):
        self.code, self.message, self.side, self.detail = code, message, side, detail


def fail(code, message, side=None, **detail):
    raise EvaluationFailure(code, message, side, **detail)


class Evaluator:
    def __init__(self, gt_dir, cand_dir, config_path=None):
        self.gt_dir, self.cand_dir = Path(gt_dir), Path(cand_dir)
        self.config_path = Path(config_path) if config_path else self.gt_dir / 'config.json'

    def run(self):
        self.report = {'protocol_version': 'dfarena-table-v3', 'passed': False,
                       'errors': [], 'diff_summary': {}, 'files': {}, 'assets': {}}
        self.current_file = None
        try:
            self.report['assets']['config_sha256'] = hashlib.sha256(self.config_path.read_bytes()).hexdigest()
            cfg = load_config(self.config_path)
        except (ConfigError, OSError) as exc:
            self._error(EvaluationFailure('CONFIG_ERROR', str(exc), 'config'))
            return self.report
        if any(s.get('alternative_gt') for s in cfg['files'].values()):
            self.report['protocol_version'] = 'dfarena-table-v4'
        if any(c.get('aliases') for s in cfg['files'].values() for c in s['columns'].values()):
            self.report['protocol_version'] = 'dfarena-table-v5'
        if any(c['type'] == 'text_exact' and c.get('aliases')
               for s in cfg['files'].values() for c in s['columns'].values()):
            self.report['protocol_version'] = 'dfarena-table-v6'
        try:
            gt = self._files(self.gt_dir, 'gt')
            cand = self._files(self.cand_dir, 'candidate')
            if set(gt) != set(cfg['files']):
                fail('CONFIG_ERROR', 'Configured files must equal GT CSV files', 'config',
                     configured=sorted(cfg['files']), gt=sorted(gt))
            if len(gt) != len(cand):
                fail('FILE_COUNT_MISMATCH', 'Candidate CSV count differs from GT', 'candidate',
                     gold=len(gt), candidate=len(cand), missing=sorted(set(gt)-set(cand)), extra=sorted(set(cand)-set(gt)))
            if set(gt) != set(cand):
                fail('MISSING_FILE', 'Candidate CSV filenames differ from GT', 'candidate',
                     missing=sorted(set(gt)-set(cand)), extra=sorted(set(cand)-set(gt)))
            for name, spec in cfg['files'].items():
                self.current_file = name
                self.report['files'][name] = {'content_status': 'not_checked',
                    'order_status': 'ignored' if spec['ignore_order'] else 'not_checked'}
                self._evaluate(gt[name], cand[name], spec)
            self.report['passed'] = True
        except EvaluationFailure as exc:
            self._error(exc)
        except Exception as exc:
            self._error(EvaluationFailure('EVALUATOR_ERROR', repr(exc), 'evaluator'))
        return self.report

    def _error(self, exc):
        error = {'error_type': exc.code, 'message': exc.message, 'side': exc.side,
                 'detail': exc.detail}
        if self.current_file:
            error['file'] = self.current_file
        self.report['errors'].append(error)
        # side locates the failed check, not a claimed program-error root cause.
        self.report['diff_summary'] = {'first_error': exc.code, 'file': self.current_file}

    def _files(self, path, side):
        if not path.is_dir():
            fail('READ_ERROR', f'Directory not found: {path}', side)
        return {p.name: p for p in sorted(path.iterdir()) if p.is_file() and p.suffix.lower() == '.csv'}

    def _read(self, path, side, columns):
        try:
            data = path.read_bytes()
            asset_name = path.relative_to(self.gt_dir).as_posix() if side == 'gt' else path.name
            self.report['assets'].setdefault(side, {})[asset_name] = hashlib.sha256(data).hexdigest()
            try:
                text = data.decode('utf-8-sig')
            except UnicodeDecodeError:
                text = data.decode('latin-1')
            reader = csv.reader(io.StringIO(text, newline=''), strict=True)
            header = next(reader, None)
            if not header or len(set(header)) != len(header):
                fail('READ_ERROR', 'Missing or duplicate CSV headers', side)
            if not set(columns) <= set(header):
                fail('MISSING_COLUMNS', 'Required columns missing', side, columns=sorted(set(columns)-set(header)))
            rows = []
            for values in reader:
                if not values:  # blank lines, as in upstream CSV loading
                    continue
                if len(values) != len(header):
                    fail('READ_ERROR', 'CSV row width differs from header', side, line=reader.line_num)
                raw = dict(zip(header, values))
                row = {}
                for col, rule in columns.items():
                    try:
                        row[col] = normalize(raw[col], rule)
                    except (ValueError, ArithmeticError) as exc:
                        fail('TYPE_ERROR', str(exc), side, row=len(rows), column=col, value=raw[col])
                rows.append(row)
            return rows
        except (OSError, csv.Error) as exc:
            fail('READ_ERROR', str(exc), side)

    def _groups(self, rows, key):
        groups = defaultdict(list)
        for i, row in enumerate(rows):
            value = tuple(row[c] for c in key)
            groups[value].append(i)
        return dict(groups)

    def _align(self, gt, cand, key, columns):
        gi, ci = self._groups(gt, key), self._groups(cand, key)
        # Reserve ALL exact groups first. A tolerant match cannot steal a later
        # exact group, so row permutation does not affect exact decisions.
        pairs = [(k, gi[k], ci[k]) for k in gi.keys() & ci.keys()]
        used = set(ci.keys() & gi.keys())
        rules = [columns[c] for c in key]
        exact_positions = [i for i, r in enumerate(rules) if r['type'] != 'number' or
                           (not r['legacy'] and r['abs_tol'] == r['rel_tol'] == 0)]
        buckets = defaultdict(list)
        for k, j in ci.items():
            if k not in used:
                buckets[tuple(k[i] for i in exact_positions)].append((k, j))
        claims = {}
        for k, gt_rows in gi.items():
            if k in used:
                continue
            matches = [(other, j) for other, j in buckets[tuple(k[n] for n in exact_positions)]
                       if all(equal(a, b, r) for a, b, r in zip(k, other, rules))]
            if not matches:
                fail('KEY_MISMATCH', 'No matching candidate key', 'comparison',
                     reason='missing_key', gt_rows=gt_rows, key=[str(x) for x in k])
            if len(matches) != 1:
                fail('KEY_MISMATCH', 'Multiple tolerant candidate groups', 'comparison',
                     reason='multiple_matches', gt_rows=gt_rows,
                     candidate_keys=[[str(x) for x in other] for other, _ in matches], count=len(matches))
            other, cand_rows = matches[0]
            if other in claims:
                fail('KEY_MISMATCH', 'Candidate group claimed by multiple GT groups', 'comparison',
                     reason='competing_matches', gt_rows=[claims[other], gt_rows], candidate_key=[str(x) for x in other])
            claims[other] = gt_rows
            pairs.append((k, gt_rows, cand_rows))
        return pairs

    def _compare_group(self, gt, cand, gt_rows, cand_rows, key, columns):
        if len(gt_rows) != len(cand_rows):
            fail('GROUP_SIZE_MISMATCH', 'Key groups contain different row counts', 'comparison',
                 gt_rows=gt_rows, candidate_rows=cand_rows,
                 gold=len(gt_rows), candidate=len(cand_rows))
        compare_cols = [c for c in columns if c not in key]
        if not compare_cols:
            return

        # Exact normalized non-key tuples can be compared as multisets. This is
        # the common duplicate-key case and is invariant to row order.
        exact_rules = all(
            rule['type'] != 'number' or
            (not rule['legacy'] and rule['abs_tol'] == rule['rel_tol'] == 0)
            for rule in (columns[c] for c in compare_cols)
        )
        if exact_rules:
            gt_counts = Counter(tuple(gt[i][c] for c in compare_cols) for i in gt_rows)
            cand_counts = Counter(tuple(cand[j][c] for c in compare_cols) for j in cand_rows)
            if gt_counts != cand_counts:
                fail('VALUE_MISMATCH', 'Duplicate-key group values differ', 'comparison',
                     gt_rows=gt_rows, candidate_rows=cand_rows,
                     gold_counts={str(k): v for k, v in gt_counts.items()},
                     candidate_counts={str(k): v for k, v in cand_counts.items()})
            return

        # For tolerant non-key values, require a one-to-one match. If multiple
        # distinct candidates satisfy one row, do not guess an alignment.
        rules = [columns[c] for c in compare_cols]
        unused = set(cand_rows)
        for i in gt_rows:
            matches = [j for j in unused if all(equal(gt[i][c], cand[j][c], r)
                                                for c, r in zip(compare_cols, rules))]
            if not matches:
                fail('VALUE_MISMATCH', 'No matching value in duplicate-key group', 'comparison',
                     gt_row=i, candidate_rows=cand_rows, columns=compare_cols)
            signatures = {tuple(cand[j][c] for c in compare_cols) for j in matches}
            if len(signatures) > 1:
                fail('AMBIGUOUS_MATCH', 'Multiple tolerant values match a row', 'comparison',
                     gt_row=i, candidate_rows=matches[:10], columns=compare_cols)
            unused.remove(matches[0])
        if unused:
            fail('VALUE_MISMATCH', 'Unmatched values remain in duplicate-key group', 'comparison',
                 candidate_rows=sorted(unused), columns=compare_cols)

    def _check_order(self, rows, order, side):
        for i in range(1, len(rows)):
            for spec in order:
                col = spec['column']
                a, b = rows[i-1][col], rows[i][col]
                if a == b:
                    continue
                if a is None or b is None:
                    correct = (a is None) == (spec['nulls'] == 'first')
                else:
                    correct = a < b if spec['direction'] == 'asc' else a > b
                if not correct:
                    fail('GT_ORDER_ERROR' if side == 'gt' else 'ROW_ORDER_MISMATCH',
                         'Adjacent rows violate order_by', side, rows=[i-1, i], column=col,
                         previous=str(a), current=str(b))
                break  # first unequal sort field decides lexicographic order

    def _evaluate(self, gt_path, cand_path, spec):
        if spec.get('alternative_gt'):
            return self._evaluate_alternatives(gt_path, cand_path, spec)
        cols = spec['columns']
        gt = self._read(gt_path, 'gt', cols)
        cand = self._read(cand_path, 'candidate', cols)
        status = self.report['files'][gt_path.name]
        status.update(gt_rows=len(gt), candidate_rows=len(cand))
        if not spec['ignore_order']:
            self._check_order(gt, spec['order_by'], 'gt')
        if len(gt) != len(cand):
            fail('ROW_COUNT_MISMATCH', 'Row counts differ', 'candidate', gold=len(gt), candidate=len(cand))
        pairs = self._align(gt, cand, spec['key'], cols)
        for _, gt_rows, cand_rows in pairs:
            self._compare_group(gt, cand, gt_rows, cand_rows, spec['key'], cols)
        status['content_status'] = 'passed'
        if not spec['ignore_order']:
            self._check_order(cand, spec['order_by'], 'candidate')
            status['order_status'] = 'passed'

    def _evaluate_alternatives(self, gt_path, cand_path, spec):
        """Accept one complete approved table, never choose a variant per row."""
        paths = {'primary': gt_path}
        for label, relative in spec['alternative_gt'].items():
            path = self.gt_dir / relative
            if not path.resolve().is_relative_to(self.gt_dir.resolve()):
                fail('CONFIG_ERROR', 'Alternative GT must stay inside the GT directory', 'config', variant=label)
            paths[label] = path
        cols = spec['columns']
        # Validate EVERY approved asset, even when the primary already matches.
        golds = {}
        for label, path in paths.items():
            try:
                golds[label] = self._read(path, 'gt', cols)
                if not spec['ignore_order']:
                    self._check_order(golds[label], spec['order_by'], 'gt')
            except EvaluationFailure as exc:
                exc.detail['variant'] = label
                raise
        cand = self._read(cand_path, 'candidate', cols)
        status = self.report['files'][gt_path.name]
        status.update(candidate_rows=len(cand), gt_rows=len(golds['primary']),
                      accepted_variants=list(paths))
        failures = []
        for label, gt in golds.items():
            try:
                if len(gt) != len(cand):
                    fail('ROW_COUNT_MISMATCH', 'Row counts differ', 'candidate', gold=len(gt), candidate=len(cand))
                for _, gi, ci in self._align(gt, cand, spec['key'], cols):
                    self._compare_group(gt, cand, gi, ci, spec['key'], cols)
                if not spec['ignore_order']:
                    self._check_order(cand, spec['order_by'], 'candidate')
                status.update(content_status='passed', matched_variant=label, gt_rows=len(gt))
                if not spec['ignore_order']:
                    status['order_status'] = 'passed'
                return
            except EvaluationFailure as exc:
                failures.append((label, exc))
        first = failures[0][1]
        first.detail['alternative_errors'] = [
            {'variant': label, 'error_type': exc.code, 'message': exc.message,
             'side': exc.side, 'detail': dict(exc.detail)} for label, exc in failures
        ]
        raise first
